using System;using System.IO;using System.Linq;using System.Drawing;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;
namespace ScoreModern {
 public sealed partial class Editor {
  internal void ProfileInteractions(string output,double startup){var lines=new List<string>();lines.Add("Native display scale="+NativeDisplay.Scale(this).ToString("F3",System.Globalization.CultureInfo.InvariantCulture));lines.Add("Startup through first message-loop pass ms="+startup.ToString("F3",System.Globalization.CultureInfo.InvariantCulture));var bytes=score.Encode();var data=NativePreferences.Read(source);var watch=Stopwatch.StartNew();DisposePreparedPreferences();preparedPreferences=CreatePreferencesDialog(data);preparedPreferencesData=data;preparedPreferencesRoot=source;watch.Stop();lines.Add("Preferences construction ms="+watch.Elapsed.TotalMilliseconds.ToString("F3"));watch.Restart();if(warmPreferencesSession!=null)warmPreferencesSession();preparedPreferences.PrepareForDisplay();watch.Stop();lines.Add("Windows preferences prewarm ms="+watch.Elapsed.TotalMilliseconds.ToString("F3"));var retained=preparedPreferences;
   for(int n=0;n<3;n++){bool painted=false;double elapsed=0;watch.Restart();PaintEventHandler paint=null;paint=(s,e)=>{if(painted)return;painted=true;elapsed=watch.Elapsed.TotalMilliseconds;retained.BeginInvoke(new Action(()=>retained.Close()));};retained.Paint+=paint;using(var timer=new Timer{Interval=5000}){timer.Tick+=(s,e)=>retained.Close();timer.Start();ShowPreferences();timer.Stop();}retained.Paint-=paint;if(!painted)throw new Exception("Preferences did not paint before diagnostic timeout.");if(!Object.ReferenceEquals(retained,preparedPreferences)||retained.IsDisposed)throw new Exception("Preferences control tree was rebuilt or disposed after modal close.");lines.Add("Cached preferences open "+n+" through first Paint ms="+elapsed.ToString("F3"));}
   bool high=NativeMouseSelector.HighResolution,points=NativeMouseSelector.ShowPoints;try{NativeMouseSelector.Set(high,true,false);int starts=GhostscriptTextRenderer.ProcessStarts;watch.Restart();PointF? before=null;for(int n=0;n<1000;n++){var point=new PointF(n%100*canvas.ClientSize.Width/100f,n/100*canvas.ClientSize.Height/10f);NativeMouseSelector.HoverChanged(canvas,before,point);NativeMouseSelector.HitTest(canvas,point);before=point;}watch.Stop();lines.Add("1000 hover-change and selection probes ms="+watch.Elapsed.TotalMilliseconds.ToString("F3"));lines.Add("Ghostscript processes during hover="+(GhostscriptTextRenderer.ProcessStarts-starts));if(GhostscriptTextRenderer.ProcessStarts!=starts)throw new Exception("Hover started Ghostscript processes.");}finally{NativeMouseSelector.Set(high,points,false);}if(!bytes.SequenceEqual(score.Encode()))throw new Exception("Interaction profile changed the score.");lines.Add("PASS cached modal reuse; first Paint observed; no score mutation; no Ghostscript process starts during hover. Timing excludes external capture and is not visual certification.");Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output)));File.WriteAllLines(output,lines);Console.WriteLine(String.Join(Environment.NewLine,lines.ToArray()));
  }
 }
 public static class NativeInteractionPerformance {public static int Run(string[] args){try{var watch=Stopwatch.StartNew();using(var editor=new Editor(args[1],args[2])){editor.Show();Application.DoEvents();watch.Stop();editor.ProfileInteractions(args[3],watch.Elapsed.TotalMilliseconds);editor.Close();}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}}
}
